bool Solution::has_cycle(ListNode *head) {
  if (head == nullptr)
    return false;

  while (head->next) {
    if (!head->next->next)
      break;
    if (head->next == head->next->next)
      return true;
    head->next = head->next->next;
    head = head->next;
  }
  return false;
}

void push(ListNode **head, const int val) {
  auto *new_node = static_cast<ListNode *>(malloc(sizeof(ListNode)));
  new_node->val = val;
  new_node->next = *head;
  *head = new_node;
}

