 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    bool hasCycle(ListNode *head) {

        //Floyd Detection Approach - Self

        if(head == NULL or head -> next == NULL)
            return false;

        ListNode * slow = head;
        ListNode * fast = head;

        while(fast != NULL and slow != NULL){

            slow = slow -> next;
            fast = fast -> next;

            if(fast != NULL)
                fast = fast -> next;

            if(slow == fast)
                return true;

        }

        return false;
    }
};

